# Client Class

class SigninghubClient(ConnectorClientBase):
    """Typed client for signinghub connector."""

    def __init__(
        self,
        connection_runtime_url: str,
        token_provider: Optional[TokenProvider] = None,
        options: Optional[ConnectorClientOptions] = None,
    ):
        """
        Initialize a SigninghubClient.

        Args:
            connection_runtime_url: The connection runtime
                URL from Azure Portal.
            token_provider: Optional token provider.
                Defaults to ManagedIdentityTokenProvider.
            options: Optional connector client options.
        """
        if not connection_runtime_url:
            raise ValueError("connection_runtime_url cannot be None or empty")

        if token_provider is None:
            token_provider = ManagedIdentityTokenProvider()

        super().__init__(token_provider, options)
        self._connection_runtime_url = connection_runtime_url.rstrip('/')

    @property
    def connector_name(self) -> str:
        return "signinghub"

    async def attachment_delete_attachment_async(
        self,
        package_id: str,
        document_id: str,
        attachment_id: str,
    ):
        """
        Delete Attachment

        Business applications can use this service API to delete the attachment
        of a document.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/v4"
            f"/packages"
            f"/{str(package_id)}"
            f"/documents"
            f"/{str(document_id)}"
            f"/attachments"
            f"/{str(attachment_id)}"
        )

        response = await self.http_client.send_async(
            "DELETE", request_url, body=None
        )

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "DELETE",
                request_url,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)

    async def attachment_download_attachment_async(
        self,
        package_id: str,
        document_id: str,
        attachment_id: str,
    ):
        """
        Download Attachment

        Business applications can use this service API to download the
        attachment of a document.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/v4"
            f"/packages"
            f"/{str(package_id)}"
            f"/documents"
            f"/{str(document_id)}"
            f"/attachments"
            f"/{str(attachment_id)}"
        )

        response = await self.http_client.send_async(
            "GET", request_url, body=None
        )

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "GET",
                request_url,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)

