    async def checkbox_add_check_box_async(
        self,
        input: CheckBoxFieldRequest,
        package_id: str,
        document_id: str,
    ):
        """
        Add CheckBox Field

        Business applications can use this service API to add a checkbox to a
        document in a package. At least one user must exist in a workflow
        before fields(input and signature) can be added to the document in this
        way.The order number corresponds to the recipient in the
        workflow.Therefore, this number must be equal or less than the total
        number of users in the workflow. The below example assigns this new
        signature field to the first person in the workflow. See [Add Users to
        Workflow](#operation/Workflow_WorkflowAddUser) for more information.
        Note if you have a document with a template applied, or have applied
        one using the APIs, then the workflow will already contain users. If
        width and height parameters are not provided, a default size of 10x10
        will be assigned. If either width or height (or both) is provided, the
        system will compare these provided values with each other. The larger
        value between width and height will be assigned to both dimensions.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/v4"
            f"/packages"
            f"/{str(package_id)}"
            f"/documents"
            f"/{str(document_id)}"
            f"/fields"
            f"/checkbox"
        )

        response = await self.http_client.send_async(
            "POST", request_url, body=input
        )

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "POST",
                request_url,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)

    async def checkbox_update_check_box_async(
        self,
        input: UpdateCheckBoxFieldRequest,
        package_id: str,
        document_id: str,
    ):
        """
        Update CheckBox Field

        Business applications can use this service API to update a checkbox
        field of a document in a package. Note all of the input parameters can
        be changed.Where you wish to retain the current setting submit it in
        the call unchanged.You can therefore use the same parameters as when
        you added the input field, or the information as returned by [Get
        Document Fields](#operation/Documents_GetDocumentFields).The latter can
        be used when a template was applied or the document was created using
        the GUI interface. It's width and height cannot be updated. They will
        remain the same as when they were added.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/v4"
            f"/packages"
            f"/{str(package_id)}"
            f"/documents"
            f"/{str(document_id)}"
            f"/fields"
            f"/checkbox"
        )

        response = await self.http_client.send_async(
            "PUT", request_url, body=input
        )

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "PUT",
                request_url,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)

