    async def fields_auto_place_async(
        self,
        input: AutoPlaceFieldRequest,
        package_id: str,
        document_id: str,
    ):
        """
        AutoPlace Fields

        Business applications can call this API to add signature or user
        defined form fields to a document based upon the search criterion
        supplied. The placement options are: to the left, to the right, top and
        bottom. The document is search and all instances of the search criteria
        met are processed. This allows you to add multiple fields with one
        call. For example, upload a document and automatically place a
        signature field to the right of all instances of the word \"Sign
        here:\". This saves time and ensures no signatures are missed from the
        workflow. The API call supports all types of fields; namely electronic,
        digital, in-person, initials, and text field etc. In addition, the API
        call supports the \"order\" variable.This means you can assign a set of
        signature fields automatically to a single user.Hence, the call can be
        repeated to place and assign signature fields to more than one user in
        the workflow. At least one user must exist in a workflow before
        signature fields can be added to the document in this way.The order
        number corresponds to the recipient in the workflow. Therefore, this
        number must be equal or less than the total number of users in the
        workflow. The below example assigns this new signature field to the
        first person in the workflow. This API call can be used multiple times
        on the same document.The reason for doing so is to cater for multiple
        signatories on a document.The recipient or signatory is identified by
        the \"order\" variable passed in the call. See [Add Users to
        Workflow](#operation/Workflow_WorkflowAddUser) for more information.
        Note if you have a document with a template applied, or have applied
        one using the APIs, then the workflow will already contain users.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/v4"
            f"/packages"
            f"/{str(package_id)}"
            f"/documents"
            f"/{str(document_id)}"
            f"/fields"
            f"/autoplace"
        )

        response = await self.http_client.send_async(
            "POST", request_url, body=input
        )

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "POST",
                request_url,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)

