    async def signing_sign_document_async(
        self,
        input: SignDocumentRequest,
        package_id: str,
        document_id: str,
    ):
        """
        Sign Document

        Business applications can use this service API to sign a document (both
        electronic and digital) without displaying the document to the end user
        using SigningHub. For example, a business application may have another
        method to display the document to the user, and only the signing
        functionality of SigningHub is required, or for bulk operations it may
        be justified to sign without requiring the user to view and approve
        every document individually. If there are changes to be saved in the
        document before signing, [Fill Form
        Fields](#operation/Documents_FillFormFields) API should be called
        before calling the Sign Document API. Note any mandatory input fields
        on a document require completing before this API will successfully
        complete. The signatory is identified by the access token presented in
        the call.Therefore, [authentication](#tag/Authentication) of the
        signatory is required prior to making this call.You cannot authenticate
        as an Enterprise Admin with the scope variable, and sign a document on
        behalf of a user.The access token must be issued to the signatory as a
        result of direct authentication. When this call completes it is
        important that if the signatory was the last signer for a document that
        the [Finish Document](#operation/Documents_Finish) API call is
        invoked.The reason is because without calling that API the document
        will remain in a status of \"In Progress\" to the document owner. Once
        the API has been called, the status will change to \"Completed\" for
        the document owner. Once document is signed, the verification response
        can be seen from [Get Document
        Verification](#operation/Documents_GetDocumentPackageVerification) API.
        First or Second Factor OTP Usage for Authentication If OTP
        authentication is turned on for the server side signing operation,
        client applications will need to generate a OTP for the mobile number
        using [Signer Authentication via
        OTP](#operation/Documents_SendOtpForField) API call. Respective
        business applications must retrieve the OTP from the use and submit it
        when making the API call. This is done using the \"x-otp\" header in
        the request.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/v4/packages/{str(package_id)}/documents/{str(document_id)}/sign"
        )

        response = await self.http_client.send_async(
            "POST", request_url, body=input
        )

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "POST",
                request_url,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)

    async def template_get_enterprise_templates_async(
        self,
        record_per_page: str,
        page_no: str,
        sort_by: Optional[str] = None,
        asc: Optional[str] = None,
        id: Optional[str] = None,
    ):
        """
        Get Enterprise Templates

        Business applications can use this service API to get list of
        enterprise templates of the current user. This means the enterprise
        administrator or the enterprise user if the \"scope\" variable was used
        in the authentication request. It is possible to search based upon the
        criterion supplied under the \"x-search-text\" header.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/v4/enterprise/templates/{str(record_per_page)}/{str(page_no)}"
        )
        query_params = []
        if sort_by is not None:
            value = str(sort_by)
            if isinstance(sort_by, bool):
                value = value.lower()
            query_params.append(f"sort-by={quote(value)}")
        if asc is not None:
            value = str(asc)
            if isinstance(asc, bool):
                value = value.lower()
            query_params.append(f"asc={quote(value)}")
        if id is not None:
            value = str(id)
            if isinstance(id, bool):
                value = value.lower()
            query_params.append(f"id={quote(value)}")
        if query_params:
            request_url += '?' + '&'.join(query_params)

        response = await self.http_client.send_async(
            "GET", request_url, body=None
        )

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "GET",
                request_url,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)

