    async def workflow_apply_template_async(
        self,
        input: ApplyTemplateRequest,
        package_id: str,
        document_id: str,
    ):
        """
        Apply Workflow Template

        Business applications can use this service API to apply a workflow
        template to a document. The document ID on which template has to be
        applied is provided in the resource URL. When document ID is set to 0
        then template will be applied to to all of the doucments in a pacakge.
        While applying the template it is important to remember these two
        important points: Point 1 - If the template being applied is created
        using a PDF which already contained form fields then ensure that the
        document on which this template is now being applied must contain these
        form fields in advance and SigningHub will NOT create those form fields
        via the template rather only apply the form data and assign to the
        respective users. Point 2 - If the template being applied is created
        where form fields are manually added (hence not present in the PDF
        originally) via SigningHub e.g. signature field, initial, in-person
        signature, check boxes, radio buttons, text fields etc. then on
        applying such a template, these form fields will be created on the
        target document even if these form fields were already present in the
        document.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/v4"
            f"/packages"
            f"/{str(package_id)}"
            f"/documents"
            f"/{str(document_id)}"
            f"/template"
        )

        response = await self.http_client.send_async(
            "POST", request_url, body=input
        )

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "POST",
                request_url,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)

